use neogenealogy_core::*;
pub trait AnalysisRule { fn id(&self)->&'static str; fn analyze(&self, tree:&GenealogyTree)->Vec<Finding>; }
pub struct MissingDataRule; pub struct ChronologyRule; pub struct ResearchGapRule;
fn f(id:String,kind:&str,s:Severity,p:Option<String>,d:String,e:Vec<String>)->Finding{Finding{id,kind:kind.into(),severity:s,person_id:p,related_person_id:None,description:d,evidence:e,confidence:0.8}}
impl AnalysisRule for MissingDataRule {fn id(&self)->&'static str{"missing-data"} fn analyze(&self,t:&GenealogyTree)->Vec<Finding>{let mut o=vec![];for p in &t.persons{for (missing,label) in [(p.birth_date.is_none(),"fecha de nacimiento"),(p.birth_place.is_none(),"lugar de nacimiento"),(p.death_date.is_none(),"fecha de defunción"),(p.death_place.is_none(),"lugar de defunción")]{if missing{o.push(f(format!("missing:{}:{}",p.gedcom_id,label),"missing-data",Severity::Low,Some(p.gedcom_id.clone()),format!("Falta {} en {}.",label,p.given_name),vec![]));}}if p.sources.is_empty(){o.push(f(format!("nosource:{}",p.gedcom_id),"missing-source",Severity::Medium,Some(p.gedcom_id.clone()),"La persona no tiene ninguna fuente asociada.".into(),vec![]));}}for fam in &t.families{if fam.marriage_date.is_none(){o.push(f(format!("missing-marriage-date:{}",fam.gedcom_id),"missing-data",Severity::Low,None,"Matrimonio sin fecha.".into(),vec![]));}if fam.marriage_place.is_none(){o.push(f(format!("missing-marriage-place:{}",fam.gedcom_id),"missing-data",Severity::Low,None,"Matrimonio sin lugar.".into(),vec![]));}}o}}
impl AnalysisRule for ChronologyRule {fn id(&self)->&'static str{"chronology"} fn analyze(&self,t:&GenealogyTree)->Vec<Finding>{let mut o=vec![];for p in &t.persons{if let(Some(b),Some(d))=(&p.birth_date,&p.death_date){if let(Some(by),Some(dy))=(b.year,d.year){if by>dy{o.push(f(format!("birth-after-death:{}",p.gedcom_id),"chronology",Severity::High,Some(p.gedcom_id.clone()),"Posible inconsistencia: nacimiento posterior a defunción.".into(),vec![format!("{} > {}",by,dy)]));}}}}for fam in &t.families{if let Some(m)=&fam.marriage_date{if let Some(my)=m.year{for pid in fam.husband_id.iter().chain(fam.wife_id.iter()){if let Some(p)=t.person(pid){if let Some(by)=p.birth_date.as_ref().and_then(|d|d.year){if my-by>90{o.push(f(format!("old-marriage:{}:{}",fam.gedcom_id,pid),"chronology",Severity::Medium,Some(pid.clone()),"Matrimonio a una edad extremadamente elevada; requiere verificación.".into(),vec![format!("nacimiento {}, matrimonio {}",by,my)]));}}}}}}}o}}
impl AnalysisRule for ResearchGapRule {fn id(&self)->&'static str{"research-gaps"} fn analyze(&self,t:&GenealogyTree)->Vec<Finding>{t.persons.iter().filter(|p|p.family_child.is_none()).map(|p|f(format!("gap:{}",p.gedcom_id),"research-gap",Severity::High,Some(p.gedcom_id.clone()),"Hueco genealógico: no se conocen los progenitores.".into(),vec![])).collect()}}
pub fn analyze(t:&GenealogyTree)->Vec<Finding>{[&MissingDataRule as &dyn AnalysisRule,&ChronologyRule,&ResearchGapRule].iter().flat_map(|r|r.analyze(t)).collect()}
